  tm: [["Mid-point", "Class centre"], ["Assumed mean", "Short-cut origin"], ["Modal class", "Class with highest frequency"], ["Quartile", "Quarter point"], ["Degrees of freedom", "n - 1 for sample variance"], ["Deviation", "Value minus mean"], ["Skewed", "Not symmetric"], ["SE", "Standard error"]],
  st: ["List the data or class table.", "Compute the mean.", "Find the median and mode.", "Compute deviations and variance.", "Take the square root for SD.", "Compute SE and CV."],
