const _axes = (x0, y0, x1, y1, xl, yl) =>
  '<line x1="' + x0 + '" y1="' + y0 + '" x2="' + x1 + '" y2="' + y0 + '" stroke="#555" stroke-width="1.3"/><line x1="' + x0 + '" y1="' + y0 + '" x2="' + x0 + '" y2="' + y1 + '" stroke="#555" stroke-width="1.3"/>' +
  _lab((x0 + x1) / 2, y0 + 30, xl, "middle") + '<text transform="translate(' + (x0 - 38) + ',' + ((y0 + y1) / 2) + ') rotate(-90)" font-size="12" fill="#17352a" text-anchor="middle">' + yl + "</text>";
const _curve = (d, col, w, dash) => '<path d="' + d + '" fill="none" stroke="' + col + '" stroke-width="' + (w || 2.5) + '"' + (dash ? ' stroke-dasharray="5 4"' : "") + "/>";
const _dash = (x1, y1, x2, y2) => '<line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '" stroke="#999" stroke-width="1" stroke-dasharray="4 3"/>';

