DIA.bmembrane = (() => {
  let s = "";
  for (let i = 0; i < 13; i++) {
    const x = 150 + i * 17;
    if (i === 6 || i === 7) continue;
    s += '<circle cx="' + x + '" cy="80" r="6" fill="#d8b46a" stroke="#1f4d3a"/><line x1="' + (x - 2) + '" y1="86" x2="' + (x - 2) + '" y2="110" stroke="#1f4d3a" stroke-width="1.4"/><line x1="' + (x + 2) + '" y1="86" x2="' + (x + 2) + '" y2="110" stroke="#1f4d3a" stroke-width="1.4"/>' +
      '<circle cx="' + x + '" cy="140" r="6" fill="#d8b46a" stroke="#1f4d3a"/><line x1="' + (x - 2) + '" y1="134" x2="' + (x - 2) + '" y2="112" stroke="#1f4d3a" stroke-width="1.4"/><line x1="' + (x + 2) + '" y1="134" x2="' + (x + 2) + '" y2="112" stroke="#1f4d3a" stroke-width="1.4"/>';
  }
  s += '<rect x="244" y="66" width="34" height="88" rx="8" fill="#b9d3e8" stroke="#2a6f97" stroke-width="1.6"/><rect x="254" y="72" width="14" height="76" fill="#f5efe0"/>' +
    '<ellipse cx="338" cy="110" rx="14" ry="20" fill="#e8c9c9" stroke="#b4572b" stroke-width="1.5"/>' +
    _call("L", 40, "Phospholipid head|(water-loving)", 160, 76) + _call("L", 112, "Fatty acid tails|(water-hating)", 170, 100) + _call("L", 190, "Cholesterol (green)|keeps it firm", 206, 106) +
    _call("R", 40, "Glycoprotein tag|on the outside", 338, 92) + _call("R", 110, "Channel protein:|ions pass through", 278, 110) + _call("R", 190, "Integral protein|spans the bilayer", 340, 124);
  s += '<ellipse cx="206" cy="98" rx="5" ry="9" fill="#fff" stroke="#6a8f4a"/><ellipse cx="300" cy="124" rx="5" ry="9" fill="#fff" stroke="#6a8f4a"/>';
  return _svg(520, 230, s, "Fluid mosaic model of the cell membrane");
})();

